/* ═══════════════ TOKENS ═══════════════ */
:root {
  --g: #dda851;
  --n: #192b45;
  --gr: #ededed;
  --w: #fff;
  --g-rgb: 221, 168, 81;
  --n-rgb: 25, 43, 69;
  --ease: cubic-bezier(0.19, 1, 0.22, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
}

ol,
ul {
  padding-left: 0 !important;
  margin-left: 0 !important;
  list-style: none;
}

a {
  text-decoration: none !important;
}

body {
  margin: 0;
  padding: 0;
}

*,
*::before,
*::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: "Quicksand", sans-serif;
  background: var(--w);
  color: var(--n);
  overflow-x: hidden;
  cursor: none;
}

img {
  display: block;
  width: 100%;
  object-fit: cover;
  pointer-events: none;
  user-select: none;
  -webkit-user-select: none;
  -webkit-user-drag: none;
  -webkit-touch-callout: none;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

/* ═══════════════ CURSOR ═══════════════ */
#cur {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 9999;
  width: 10px;
  height: 10px;
  background: var(--g);
  border-radius: 50%;
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition:
    width 0.3s,
    height 0.3s,
    opacity 0.3s;
  mix-blend-mode: exclusion;
}

#cur-ring {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 9998;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(var(--g-rgb), 0.5);
  border-radius: 50%;
  pointer-events: none;
  transform: translate(-50%, -50%);
  transition:
    width 0.5s var(--ease),
    height 0.5s var(--ease),
    border-color 0.3s;
}

.hovering #cur {
  width: 16px;
  height: 16px;
}

.hovering #cur-ring {
  width: 68px;
  height: 68px;
  border-color: rgba(var(--g-rgb), 0.8);
}

/* ═══════════════ NAV ═══════════════ */
nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 900;
  display: flex;
  align-items: center;
  justify-content: space-between;
  /* padding: 30px 64px; */
  padding-top: 30px;
  padding-bottom: 15px;
  padding-left: 64px;
  padding-right: 64px;
  transition:
    padding 0.6s var(--ease),
    background 0.5s,
    box-shadow 0.5s;
}

nav.stuck {
  padding: 16px 64px;
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(24px);
  box-shadow: 0 1px 0 rgba(var(--n-rgb), 0.07);
}

.wm {
  display: flex;
  flex-direction: column;
  line-height: 1;
  text-decoration: none;
}

.wm .logo {
  width: clamp(176px, 12vw, 240px);
  height: auto;
  display: block;
  will-change: opacity, filter, transform;
  animation: logoReveal 0.9s var(--ease) both, logoFloat 5.8s ease-in-out 0.9s infinite;
}

footer .logo {
  display: block;
  will-change: opacity, filter, transform;
  animation: logoReveal 0.9s var(--ease) both, logoFloat 5.8s ease-in-out 0.9s infinite;
}

.wm-main {
  font-family: "League Spartan", sans-serif;
  font-size: 40px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--w);
  transition: color 0.4s;
}

.wm-main .dot {
  color: var(white);
}

.wm-sub {
  font-family: "Quicksand", sans-serif;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
  margin-top: 3px;
  transition: color 0.4s;
}

nav.stuck .wm-main {
  color: var(--n);
}

nav.stuck .wm-sub {
  color: rgba(var(--n-rgb), 0.35);
}

.nav-links {
  display: flex;
  gap: 36px;
}

.nav-links a {
  font-family: "Quicksand", sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.75);
  position: relative;
  transition: color 0.3s;
}

.nav-links a::after {
  content: "";
  position: absolute;
  bottom: -4px;
  left: 50%;
  width: 0;
  height: 1px;
  background: var(--g);
  transform: translateX(-50%);
  transition: width 0.4s var(--ease);
}

.nav-links a:hover,
.nav-links a.act {
  color: var(--g);
}

.nav-links a:hover::after,
.nav-links a.act::after {
  width: 100%;
}

@keyframes logoReveal {
  0% {
    opacity: 0;
    filter: blur(8px);
  }

  100% {
    opacity: 1;
    filter: blur(0);
  }
}

@keyframes logoFloat {
  0%,
  100% {
    transform: translateY(0);
  }

  50% {
    transform: translateY(-4px);
  }
}

nav.stuck .nav-links a {
  color: var(--n);
}

nav.stuck .nav-links a:hover {
  color: var(--g);
}

.ncta-group {
  display: flex;
  align-items: center;
  gap: 12px;
}

.ncta {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  background: var(--g);
  /* Normal yellow */
  padding: 11px 28px;
  border: 1px solid var(--g);
  color: var(--w);
  position: relative;
  overflow: hidden;
  transition:
    color 0.3s,
    border-color 0.3s,
    background 0.3s;
}

.ncta::before {
  content: "";
  position: absolute;
  inset: 0;
  background: transparent;
  transform: translateY(102%);
  transition: transform 0.45s var(--ease);
}

.ncta span {
  position: relative;
  z-index: 1;
}

.ncta:hover {
  background: transparent;
  /* Hover transparent */
  color: var(--w);
  border-color: rgba(255, 255, 255, 0.3);
}

.ncta:hover::before {
  transform: translateY(0);
}

nav.stuck .ncta {
  border-color: rgba(var(--n-rgb), 0.25);
  color: var(--n);
}

nav.stuck .ncta:hover {
  color: var(--n);
}

.ncta.ncta-ghost {
  background: transparent;
  color: var(--g);
}

.ncta.ncta-ghost:hover {
  background: var(--g);
  color: var(--w);
  border-color: var(--g);
}

nav.stuck .ncta.ncta-ghost {
  border-color: var(--g);
  color: var(--g);
}

nav.stuck .ncta.ncta-ghost:hover {
  color: var(--w);
}

.ham {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: none;
  border: 0;
  background: transparent;
  padding: 6px;
}

.ham span {
  width: 22px;
  height: 1.5px;
  background: var(--w);
  display: block;
  transition: background 0.4s;
}

nav.stuck .ham span {
  background: var(--n);
}

/* Mobile left sidebar (hamburger) */
.mnav-backdrop {
  position: fixed;
  inset: 0;
  z-index: 905;
  background: rgba(0, 0, 0, 0.36);
  opacity: 0;
  transition: opacity 0.25s var(--ease-out);
}

.mnav {
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  width: min(360px, 88vw);
  z-index: 906;
  background: rgba(255, 255, 255, 0.96);
  backdrop-filter: blur(22px);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.18);
  transform: translateX(-104%);
  transition: transform 0.35s var(--ease);
  padding: 18px 18px 22px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.mnav.is-open {
  transform: translateX(0);
}

.mnav-backdrop.is-open {
  opacity: 1;
}

body.mnav-open {
  overflow: hidden;
  touch-action: none;
}

.mnav-head {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding-top: 6px;
}

.mnav-brand {
  display: flex;
  flex-direction: column;
  line-height: 1;
  text-align: center;
}

.mnav-logo {
  font-family: "League Spartan", sans-serif;
  font-size: 32px;
  font-weight: 800;
  letter-spacing: 0.05em;
  color: var(--n);
}

.mnav-logo .dot {
  color: var(--g);
}

.mnav-sub {
  font-family: "Quicksand", sans-serif;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.45);
  margin-top: 3px;
}

.mnav-close {
  position: absolute;
  top: 0;
  right: 0;
  width: 40px;
  height: 40px;
  border-radius: 12px;
  border: 1px solid rgba(var(--n-rgb), 0.12);
  background: rgba(255, 255, 255, 0.7);
  color: rgba(var(--n-rgb), 0.75);
  font-size: 26px;
  line-height: 1;
  cursor: none;
  pointer-events: auto;
}

.mnav-links {
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding-top: 0;
  margin-top: 95px;
  align-items: center;
  text-align: center;
  flex: 1;
  justify-content: flex-start;
}

.mnav-links a {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 18px;
  border-radius: 999px;
  font-family: "Quicksand", sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.78);
  transition:
    background 0.2s,
    color 0.2s;
  width: min(280px, 100%);
}

.mnav-links a:hover,
.mnav-links a.act {
  background: rgba(var(--g-rgb), 0.16);
  color: var(--n);
}

.mnav-cta {
  margin-top: auto;
  margin-bottom: 10px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 16px;
  border-radius: 16px;
  background: var(--g);
  color: var(--n);
  font-family: "Quicksand", sans-serif;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

@media (min-width: 1101px) {

  .mnav,
  .mnav-backdrop {
    display: none !important;
  }
}

/* ═══════════════ PAGE SYSTEM ═══════════════ */
.page {
  display: none;
}

.page.active {
  display: block;
}

/* ═══════════════ SHARED ═══════════════ */
.eb {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 18px;
}

.eb-line {
  width: 36px;
  height: 1px;
  background: var(--g);
  flex-shrink: 0;
}

.eb-t {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  color: var(--g);
}

.stitle {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(36px, 5vw, 68px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
  color: var(--n);
}

.stitle.wh {
  color: var(--w);
}

.stitle .th {
  font-weight: 200;
}

.sec {
  padding: 140px 64px;
}

/* Reveal animations */
.rv {
  opacity: 0;
  transform: translateY(44px);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}

.rv.on {
  opacity: 1;
  transform: none;
}

.rvl {
  opacity: 0;
  transform: translateX(-44px);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}

.rvl.on {
  opacity: 1;
  transform: none;
}



.rvr {
  opacity: 0;
  transform: translateX(44px);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}

.rvr.on {
  opacity: 1;
  transform: none;
}

.rvs {
  opacity: 0;
  transform: scale(0.94);
  transition:
    opacity 0.9s var(--ease),
    transform 0.9s var(--ease);
}

.rvs.on {
  opacity: 1;
  transform: scale(1);
}

[data-d="1"] {
  transition-delay: 0.1s;
}

[data-d="2"] {
  transition-delay: 0.2s;
}

[data-d="3"] {
  transition-delay: 0.3s;
}

[data-d="4"] {
  transition-delay: 0.4s;
}

[data-d="5"] {
  transition-delay: 0.5s;
}

[data-d="6"] {
  transition-delay: 0.6s;
}

/* Buttons */
.mbtn {
  position: relative;
  overflow: hidden;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 17px 46px;
  cursor: none;
  transition: transform 0.15s;
}

.mbtn-bg {
  position: absolute;
  inset: 0;
  background: var(--g);
  transition: transform 0.45s var(--ease);
}

.mbtn:hover .mbtn-bg {
  transform: scale(1.07);
}

.mbtn-lbl {
  position: relative;
  z-index: 1;
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--n);
  white-space: nowrap;
}

.mbtn.dk .mbtn-bg {
  background: var(--n);
}

.mbtn.dk .mbtn-lbl {
  color: var(--w);
}

.gbtn {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.65);
  transition:
    color 0.3s,
    gap 0.4s var(--ease);
  cursor: none;
}

.gbtn .gl {
  width: 36px;
  height: 1px;
  background: currentColor;
  transition: width 0.45s var(--ease);
}

.gbtn:hover {
  color: var(--g);
  gap: 22px;
}

.gbtn:hover .gl {
  width: 60px;
}

.gbtn.dark {
  color: rgba(var(--n-rgb), 0.5);
}

.gbtn.dark:hover {
  color: var(--g);
}

/* Marquee */
.mqw {
  overflow: hidden;
  background: var(--g);
  padding: 22px 0;
}

.mqt {
  display: flex;
  gap: 52px;
  white-space: nowrap;
  animation: mqs 26s linear infinite;
  width: max-content;
}

.mqi {
  font-family: "League Spartan", sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--n);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 26px;
}

.mqd {
  width: 4px;
  height: 4px;
  background: var(--n);
  border-radius: 50%;
  opacity: 0.3;
}

@keyframes mqs {
  from {
    transform: translateX(0);
  }

  to {
    transform: translateX(-50%);
  }
}

/* Page hero (inner pages) */
.ph {
  position: relative;
  height: 60vh;
  min-height: 550px;
  padding-top: 150px;
  display: flex;
  align-items: flex-end;
  overflow: hidden;
}

@media (max-width: 1199px) {
  .ph {
    min-height: 500px;
    padding-top: 120px;
  }
}

@media (max-width: 826px) {
  .ph {
    height: auto;
    min-height: 200px;
    padding-top: 0;
    align-items: flex-start;
  }

  .ph-body {
    padding-top: 120px !important;
    padding-bottom: 40px !important;
    padding-left: 24px !important;
    padding-right: 24px !important;
    max-width: 100% !important;
  }
}

.ph-pbg {
  position: absolute;
  inset: -20%;
  background-size: cover;
  background-position: center;
  will-change: transform;
}

.ph-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg,
      rgba(var(--n-rgb), 0.92) 0%,
      rgba(var(--n-rgb), 0.6) 60%,
      rgba(var(--n-rgb), 0.25) 100%);
}

.ph-body {
  position: relative;
  z-index: 2;
  padding: 20px 0px 64px 80px;
  max-width: 800px;
}

.ph-tag {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 28px;
}

.ph-tag-line {
  width: 40px;
  height: 1px;
  background: var(--g);
}

.ph-tag span {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.38em;
  text-transform: uppercase;
  color: var(--g);
}

.ph-title {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(52px, 8vw, 80px);
  font-weight: 900;
  line-height: 0.92;
  letter-spacing: -0.025em;
  color: var(--w);
  margin-bottom: 24px;
}

.ph-title .gold {
  color: var(--g);
}

.ph-sub {
  font-family: "Quicksand", sans-serif;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.75);
  max-width: 420px;
}

/* ═══════════════ HOME — HERO ═══════════════ */
.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  overflow: hidden;
  padding-top: 110px;
}

/* Parallax layers */
.p-layer {
  position: absolute;
  will-change: transform;
}

.hero-bg-img {
  inset: -25%;
   background-image: url("assets/Images/Jomo_hero.webp");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}
 

.hero-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg,
      rgba(var(--n-rgb), 0.93) 0%,
      rgba(var(--n-rgb), 0.62) 52%,
      rgba(var(--n-rgb), 0.28) 100%);
}

/* subtle floating gradient orb */
.hero-orb {
  position: absolute;
  top: 10%;
  right: 5%;
  width: 45vw;
  height: 80vh;
  background: radial-gradient(ellipse at 60% 40%,
      rgba(var(--g-rgb), 0.1) 0%,
      transparent 70%);
  pointer-events: none;
}

.hero-body {
  position: relative;
  z-index: 2;
  padding: 0 64px;
  max-width: 100%;
  width: 100%;
  display: flex;
  align-items: flex-start;
  gap: 40px;
}

.hero-body>[class*="col-"] {
  flex: 1;
  min-width: 0;
}

.hero-body>[class*="col-"]:last-child {
  margin-top: 0;
}

.h-tag {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 36px;
  color: var(--g);
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.4em;
  text-transform: uppercase;
  opacity: 0;
  animation: fu 0.8s 0.2s var(--ease) forwards;
}

.h-tag-line {
  width: 44px;
  height: 1px;
  background: var(--g);
}

.hero h1 {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(56px, 8vw, 85px);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.025em;
  color: var(--w);
  margin-bottom: 36px;
}

.hero h1 .line {
  display: block;
  overflow: hidden;
}

.hero h1 .li {
  display: block;
  opacity: 0;
  transform: translateY(110%);
  animation: lu 0.95s var(--ease) forwards;
}

.l1 .li {
  animation-delay: 0.38s;
}

.l2 .li {
  animation-delay: 0.54s;
}

.l3 .li {
  animation-delay: 0.7s;
}

.hero h1 .gold {
  color: var(--g);
}

.hero-sub {
  font-size: 17px;
  font-weight: 500;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.78);
  max-width: 440px;
  margin-bottom: 52px;
  opacity: 0;
  animation: fu 0.8s 0.9s var(--ease) forwards;
}

.hero-acts {
  display: flex;
  gap: 22px;
  align-items: center;
  flex-wrap: wrap;
  opacity: 0;
  animation: fu 0.8s 1.05s var(--ease) forwards;
}

/* Hero Form Styles */
.hero-form {
  background: rgba(var(--n-rgb), 0.4);
  backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  padding: 16px;
  opacity: 0;
  animation: fu 0.8s 1.05s var(--ease) forwards;
  margin: 0;
  height: fit-content;
  max-width: 360px;
  margin-left: auto;
}

.hero-form-title {
  font-family: "League Spartan", sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--w);
  margin-bottom: 6px;
}

.hero-form-sub {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 10px;
}

.hero-form-fields {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.hero-form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.hero-form-lbl {
  font-size: 11px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.8);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.hero-form-inp {
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  color: var(--w);
  font-family: "Quicksand", sans-serif;
  font-size: 13px;
  transition: all 0.2s ease;
}

@media (max-width: 768px) {
  .wm .logo {
    width: clamp(106px, 30vw, 132px);
  }

  .hero-form {
    max-width: calc(92vw);
    padding: 12px;
    border-radius: 8px;
  }
  .hero-form-title { font-size: 16px; }
  .hero-form-sub { font-size: 12px; }
}

.hero-form-inp::placeholder {
  color: rgba(255, 255, 255, 0.4);
}

.hero-form-inp:focus {
  outline: none;
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(221, 168, 81, 0.5);
  box-shadow: 0 0 0 3px rgba(221, 168, 81, 0.1);
}

.hero-notice {
  min-height: 0px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.7);
}

.hero-scroll {
  position: absolute;
  bottom: 48px;
  left: 64px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  opacity: 0;
  animation: fu 0.8s 1.3s forwards;
}


.hs-bar {
  width: 1px;
  height: 64px;
  background: rgba(var(--g-rgb), 0.2);
  position: relative;
  overflow: hidden;
}

.hs-bar::after {
  content: "";
  position: absolute;
  top: -100%;
  left: 0;
  width: 1px;
  height: 45%;
  background: var(--g);
  animation: pip 2.2s var(--ease) infinite;
}

.hs-lbl {
  font-family: "Quicksand", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.35em;
  text-transform: uppercase;
  color: #ffffff;
  writing-mode: vertical-lr;
}

@keyframes pip {
  to {
    top: 200%;
  }
}

.hero-strip {
  position: absolute;
  bottom: 0;
  right: 0;
  z-index: 2;
  display: flex;
  opacity: 0;
  animation: fu 0.8s 1.1s forwards;
}

.hsi {
  padding: 28px 38px;
  border-left: 1px solid rgba(255, 255, 255, 0.07);
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  backdrop-filter: blur(6px);
  background: rgba(var(--n-rgb), 0.3);
}

.hsi-n {
  font-family: "League Spartan", sans-serif;
  font-size: 40px;
  font-weight: 900;
  color: var(--g);
  display: block;
  line-height: 1;
}

.hsi-l {
  font-family: "Quicksand", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
  display: block;
  margin-top: 4px;
}

@keyframes fu {
  from {
    opacity: 0;
    transform: translateY(22px);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes lu {
  from {
    opacity: 0;
    transform: translateY(110%);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

/* ═══════════════ PHILOSOPHY ═══════════════ */
.philosophy {
  background: var(--n);
  padding: 60px 64px;
  position: relative;
  overflow: hidden;
}

.phil-bg-orb {
  position: absolute;
  bottom: -20%;
  left: -10%;
  width: 60vw;
  height: 60vw;
  background: radial-gradient(circle,
      rgba(var(--g-rgb), 0.07) 0%,
      transparent 65%);
  pointer-events: none;
}

.phil-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 100px;
  align-items: center;
  position: relative;
  z-index: 1;
}

.phil-quote {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(22px, 3vw, 40px);
  font-weight: 300;
  line-height: 1.25;
  color: var(--w);
  letter-spacing: -0.01em;
  margin-bottom: 28px;
}

.phil-quote .gold {
  color: var(--g);
}

.phil-body {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.9;
  color: rgba(255, 255, 255, 0.62);
  margin-bottom: 28px;
}

.phil-body strong {
  color: var(--w);
  font-weight: 700;
}

.phil-divider {
  width: 48px;
  height: 1px;
  background: rgba(var(--g-rgb), 0.4);
  margin-bottom: 28px;
}

.phil-cards {
  display: flex;
  flex-direction: column;
  gap: 1px;
  background: rgba(255, 255, 255, 0.06);
}

.pc {
  background: var(--n);
  padding: 36px 40px;
  position: relative;
  overflow: hidden;
  transition: background 0.4s;
}

.pc::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 3px;
  height: 0;
  background: var(--g);
  transition: height 0.5s var(--ease);
}

.pc:hover {
  background: rgba(var(--g-rgb), 0.07);
}

.pc:hover::before {
  height: 100%;
}

.pc-h {
  font-family: "League Spartan", sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--w);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.pc-p {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.8;
  color: rgba(255, 255, 255, 0.55);
}

/* ═══════════════ PARALLAX STORY SPLIT ═══════════════ */
.story-split {
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 640px;
}

.ss-img {
  position: relative;
  overflow: hidden;
}

.ss-img-inner {
  position: absolute;
  inset: -20%;
  background-size: cover;
  background-position: center;
  will-change: transform;
}

.ss-img-veil {
  position: absolute;
  inset: 0;
  background: rgba(var(--n-rgb), 0.3);
}

.ss-copy {
  background: var(--gr);
  padding: 80px 72px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 26px;
}

.ss-lead {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(20px, 2vw, 28px);
  font-weight: 300;
  line-height: 1.35;
  color: var(--n);
}

.ss-body {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.9;
  color: rgba(var(--n-rgb), 0.6);
}

.ss-body strong {
  color: var(--n);
  font-weight: 700;
}

.ss-pills {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(var(--n-rgb), 0.1);
  margin-top: 8px;
}

.ss-pill {
  background: var(--gr);
  padding: 24px 18px;
  position: relative;
}

.ss-pill::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--g);
  transition: width 0.45s var(--ease);
}

.ss-pill:hover::after {
  width: 100%;
}

.ss-pill-n {
  font-family: "League Spartan", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: var(--g);
  margin-bottom: 8px;
}

.ss-pill-h {
  font-family: "League Spartan", sans-serif;
  font-size: 15px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--n);
  margin-bottom: 5px;
}

.ss-pill-p {
  font-size: 12px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.5);
  line-height: 1.65;
}

/* ═══════════════ CRAFTSMANSHIP ═══════════════ */
.craft {
  background: var(--w);
  padding: 160px 64px;
}

.craft-grid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: clamp(40px, 6vw, 84px);
  align-items: center;
}

.craft-images {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  grid-auto-rows: clamp(280px, 28vw, 460px);
  align-items: stretch;
}

.ci-main {
  width: 100%;
  height: 100%;
  object-fit: cover;
  will-change: transform;
  border-radius: 14px;
}

.ci-accent {
  width: 100%;
  height: 100%;
  object-fit: cover;
  will-change: transform;
  border-radius: 14px;
}

.ci-badge {
  position: absolute;
  top: 50%;
  left: 55%;
  transform: translate(-50%, -50%);
  background: var(--g);
  width: 112px;
  height: 112px;
  border-radius: 50%;
  z-index: 3;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  box-shadow: 0 16px 48px rgba(var(--g-rgb), 0.4);
}

.ci-badge strong {
  font-family: "League Spartan", sans-serif;
  font-size: 32px;
  font-weight: 900;
  color: var(--n);
  line-height: 1;
}

.ci-badge span {
  font-family: "Quicksand", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--n);
  opacity: 0.65;
}

.craft-copy {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.craft-lead {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(18px, 2vw, 26px);
  font-weight: 300;
  line-height: 1.35;
  color: var(--n);
}

.craft-body {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.9;
  color: rgba(var(--n-rgb), 0.6);
}

.craft-body strong {
  color: var(--n);
  font-weight: 700;
}

.cf-list {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.cf-item {
  display: flex;
  gap: 20px;
  padding: 22px 0;
  border-bottom: 1px solid rgba(var(--n-rgb), 0.07);
}

.cf-n {
  font-family: "League Spartan", sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.15em;
  color: rgba(var(--g-rgb), 0.7);
  width: 24px;
  flex-shrink: 0;
  padding-top: 3px;
}

.cf-h {
  font-family: "League Spartan", sans-serif;
  font-size: 15px;
  font-weight: 700;
  color: var(--n);
  text-transform: uppercase;
  letter-spacing: 0.03em;
  margin-bottom: 5px;
}

.cf-p {
  font-size: 13px;
  font-weight: 500;
  line-height: 1.7;
  color: rgba(var(--n-rgb), 0.5);
}

/* ═══════════════ EXPERIENCE CENTRE ═══════════════ */
.exp-sec {
  background: var(--n);
  padding: 160px 64px;
  position: relative;
  overflow: hidden;
}

.exp-bg-layer {
  position: absolute;
  inset: 0;
  opacity: 0.07;
  will-change: transform;
}

.exp-bg-layer img {
  width: 100%;
  height: 130%;
  object-fit: cover;
}

.exp-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 100px;
  align-items: center;
  position: relative;
  z-index: 1;
}

.exp-copy {
  display: flex;
  flex-direction: column;
  gap: 26px;
}

.exp-lead {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(20px, 2.5vw, 32px);
  font-weight: 300;
  line-height: 1.3;
  color: var(--w);
}

.exp-lead .gold {
  color: var(--g);
}

.exp-body {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.9;
  color: rgba(255, 255, 255, 0.62);
}

.exp-feats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: rgba(255, 255, 255, 0.06);
}

.ef {
  background: var(--n);
  padding: 28px 24px;
  transition: background 0.4s;
}

.ef:hover {
  background: rgba(var(--g-rgb), 0.07);
}

.ef-dot {
  width: 8px;
  height: 8px;
  background: var(--g);
  border-radius: 50%;
  margin-bottom: 14px;
}

.ef-h {
  font-family: "League Spartan", sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: var(--w);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 6px;
}

.ef-p {
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
  line-height: 1.65;
}

.exp-img-wrap {
  position: relative;
}

.exp-img {
  height: 480px;
  object-fit: cover;
  width: 100%;
  display: block;

}

.exp-tag {
  position: absolute;
  bottom: -24px;
  left: -24px;
  background: var(--g);
  padding: 30px 34px;
}

.exp-tag strong {
  font-family: "League Spartan", sans-serif;
  font-size: 18px;
  font-weight: 700;
  color: var(--n);
  display: block;
  margin-bottom: 4px;
}

.exp-tag span {
  font-family: "Quicksand", sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.65);
}

/* ═══════════════ PARALLAX QUOTE BANNER ═══════════════ */
.quote-band {
  position: relative;
  height: 70vh;
  min-height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  text-align: center;
}

.qb-pbg {
  position: absolute;
  inset: -25%;
  background: url("data:image/png;base64,") center/cover;
  will-change: transform;
}

.qb-veil {
  position: absolute;
  inset: 0;
  background: rgba(var(--n-rgb), 0.86);
}

.qb-body {
  position: relative;
  z-index: 2;
  padding: 0 80px;
  max-width: 900px;
}

.qb-mark {
  font-family: "League Spartan", sans-serif;
  font-size: 140px;
  font-weight: 900;
  color: rgba(var(--g-rgb), 0.1);
  line-height: 0.65;
  margin-bottom: -10px;
  display: block;
}

.qb-text {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(26px, 3.5vw, 50px);
  font-weight: 300;
  line-height: 1.2;
  color: var(--w);
  letter-spacing: -0.01em;
}

.qb-text em {
  font-style: italic;
  color: var(--g);
}

.qb-src {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 22px;
  margin-top: 34px;
}

.qb-src-line {
  width: 44px;
  height: 1px;
  background: rgba(var(--g-rgb), 0.4);
}

.qb-src span {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
}

/* ═══════════════ PROJECTS ═══════════════ */
.home-proj {
  background: var(--w);
  padding: 160px 0;
}

.hp-head {
  padding: 0 64px;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 56px;
}

.va {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--n);
  transition:
    color 0.3s,
    gap 0.4s var(--ease);
}

.va-line {
  width: 30px;
  height: 1px;
  background: currentColor;
}

.va:hover {
  color: var(--g);
  gap: 22px;
}

.ptrack {
  display: flex;
  gap: 4px;
  padding: 0 64px;
  overflow-x: auto;
  scrollbar-width: none;
}

.ptrack::-webkit-scrollbar {
  display: none;
}

.pcard {
  flex: 0 0 460px;
  height: 580px;
  position: relative;
  overflow: hidden;
  cursor: none;
}

.pcard img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  transform: scale(1);
  transition:
    transform 0.95s var(--ease),
    filter 0.5s;
  filter: grayscale(20%);
}

.pcard:hover img {
  transform: scale(1.03);
  filter: grayscale(0);
}

.pcard-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top,
      rgba(var(--n-rgb), 0.9) 0%,
      rgba(var(--n-rgb), 0.05) 55%,
      transparent 100%);
}

.pcard-info {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 34px 30px;
  transform: translateY(10px);
  transition: transform 0.55s var(--ease);
}

.pcard:hover .pcard-info {
  transform: none;
}

.pcard-cat {
  font-family: "Quicksand", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 8px;
}

.pcard-name {
  font-family: "League Spartan", sans-serif;
  font-size: 24px;
  font-weight: 700;
  color: var(--w);
  margin-bottom: 4px;
}

.pcard-loc {
  font-size: 12px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
}

.pcard-tag {
  position: absolute;
  top: 22px;
  right: 22px;
  background: var(--g);
  padding: 5px 14px;
  font-family: "Quicksand", sans-serif;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--n);
}

/* ── Project Lightbox ── */
.project-lightbox {
  position: fixed;
  inset: 0;
  z-index: 9999;
  display: none;
  align-items: center;
  justify-content: center;
  gap: clamp(14px, 2.8vw, 42px);
  padding: clamp(18px, 4vw, 54px);
  background: rgba(9, 14, 23, 0.82);
  backdrop-filter: blur(12px);
  cursor: default;
}

.project-lightbox *,
.project-lightbox button {
  cursor: inherit;
}

.project-lightbox button {
  cursor: pointer;
}

.project-lightbox.is-open {
  display: flex;
}

.project-lightbox::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(255, 255, 255, 0.06), transparent 52%);
  pointer-events: none;
}

/* side panels hold arrow + client-hint label */
.plb-side {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  width: clamp(96px, 10vw, 160px);
  flex-shrink: 0;
  z-index: 10;
}

.plb-side-prev {
  align-items: flex-end;
}

.plb-side-next {
  align-items: flex-start;
}

/* client-hint label */
.plb-client-hint {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--g);
  opacity: 0;
  transform: translateY(4px);
  transition: opacity 0.3s ease, transform 0.3s ease;
  text-align: center;
  pointer-events: none;
  line-height: 1.5;
  max-width: 140px;
  white-space: pre-line;
}
.plb-client-hint.visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

/* dialog (the image box) */
.plb-dialog {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  max-width: min(880px, calc(100vw - 320px));
  max-height: min(780px, 86vh);
  background: rgba(10, 14, 22, 0.94);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.5);
  overflow: hidden;
  border-radius: 30px;
}

.plb-img {
  display: block;
  width: 100%;
  height: min(680px, 78vh);
  object-fit: cover;
  background: transparent;
  transition: opacity 0.25s ease;
}

.plb-caption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 28px clamp(20px, 4vw, 42px);
  background: linear-gradient(to top, rgba(4, 8, 14, 0.9), rgba(4, 8, 14, 0));
  color: var(--w);
}

.project-lightbox.lightbox-minimal .plb-caption {
  display: none;
}

.plb-kicker {
  display: block;
  margin-bottom: 6px;
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--g);
}

.plb-title {
  margin: 0 0 4px;
  font-family: "League Spartan", sans-serif;
  font-size: clamp(22px, 3.5vw, 38px);
  line-height: 1;
  color: var(--w);
}

.plb-counter {
  margin: 0;
  font-family: "Quicksand", sans-serif;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.12em;
  color: rgba(255, 255, 255, 0.65);
}

/* close button — top-right of lightbox overlay */
.plb-close {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 20;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  padding: 0;
  border: 2px solid var(--g);
  border-radius: 50%;
  background: rgba(7, 12, 20, 0.9);
  color: #fff;
  line-height: 0;
  cursor: pointer;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.4), 0 0 0 5px rgba(224, 171, 76, 0.1);
  transition: background 0.25s ease, transform 0.25s ease, border-color 0.25s ease;
}
.plb-close:hover {
  background: var(--g);
  border-color: var(--g);
  color: var(--n);
  transform: scale(1.08);
}

/* arrow buttons — inside .plb-side, NOT absolutely positioned */
.plb-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  padding: 0;
  border: 2px solid var(--g);
  border-radius: 50%;
  background: rgba(7, 12, 20, 0.88);
  color: #fff;
  cursor: pointer;
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.35), 0 0 0 6px rgba(224, 171, 76, 0.12);
  transition: background 0.25s ease, transform 0.25s ease, border-color 0.25s ease;
  flex-shrink: 0;
}
.plb-arrow:hover {
  background: var(--g);
  border-color: var(--g);
  color: var(--n);
  transform: scale(1.08);
}

.project-lightbox button:focus-visible {
  outline: 2px solid var(--g);
  outline-offset: 4px;
}

.project-lightbox button svg {
  display: block;
  width: 18px;
  height: 18px;
  stroke: currentColor;
  stroke-width: 2.4;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}

/* Testimonials */
.testi {
  background: var(--gr);
  padding: 140px 64px;
}

.tc-carousel {
  margin-top: 72px;
}

.tc-outer {
  display: flex;
  align-items: center;
  gap: 24px;
}

.tc-slider {
  flex: 1;
  overflow: hidden;
  min-width: 0;
}

.tc-track {
  display: flex;
  transition: transform 0.65s cubic-bezier(0.19, 1, 0.22, 1);
  will-change: transform;
}

.tc {
  flex-shrink: 0;
  background: var(--w);
  padding: 40px 36px;
  transition: background 0.4s;
  border: 1px solid rgba(var(--n-rgb), 0.07);
  box-sizing: border-box;
}

.tc:hover {
  background: rgba(var(--g-rgb), 0.04);
}

.tc-arrow {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1.5px solid rgba(var(--n-rgb), 0.18);
  background: var(--w);
  color: var(--n);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.3s, color 0.3s, border-color 0.3s;
}

.tc-arrow:hover {
  background: var(--g);
  border-color: var(--g);
  color: var(--w);
}

.tc-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 28px;
}

.tc-dot {
  width: 8px;
  height: 8px;
  border-radius: 100px;
  background: rgba(var(--n-rgb), 0.2);
  border: none;
  cursor: pointer;
  padding: 0;
  transition: background 0.3s, width 0.3s;
}

