}

.si-body {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.85;
  color: rgba(var(--n-rgb), 0.6);
}

.si-copy.bg-dark .si-body {
  color: rgba(255, 255, 255, 0.6);
}

.si-feats {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.si-feat {
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.si-feat-dot {
  width: 5px;
  height: 5px;
  background: var(--g);
  border-radius: 50%;
