}

.si-feat-txt {
  font-size: 13px;
  font-weight: 600;
  color: rgba(var(--n-rgb), 0.6);
}

.si-copy.bg-dark .si-feat-txt {
  color: rgba(255, 255, 255, 0.5);
}

.svc-why {
  background: var(--n);
  padding: 130px 64px;
  border-bottom: 1px #DDA851 solid;
}

.sw-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: rgba(255, 255, 255, 0.06);
  margin-top: 72px;
}

.swi {
  background: var(--n);
  padding: 44px 36px;
