}

.swi-h {
  font-family: "League Spartan", sans-serif;
  font-size: 16px;
  font-weight: 700;
  color: var(--w);
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.swi-p {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.75;
  color: rgba(255, 255, 255, 0.5);
}

/* ═══════════════ PROCESS PAGE ═══════════════ */
.proc-intro {
  background: var(--w);
  padding: 130px 64px 0px 80px;
}

.proc-body {
  font-size: 16px;
  font-weight: 500;
  line-height: 1.9;
  color: rgba(var(--n-rgb), 0.6);
  max-width: 600px;
  margin-top: 24px;
}

.proc-steps {
  background: var(--w);
  padding: 40px 64px 130px;
}

.pstep {
