  grid-template-columns: 180px 1fr;
  gap: 60px;
  padding: 64px 0;
  border-top: 1px solid rgba(var(--n-rgb), 0.07);
}

.pstep-l {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.pstep-n {
  font-family: "League Spartan", sans-serif;
  font-size: 84px;
  font-weight: 900;
  color: #DDA851;
  line-height: 0.85;
}

.pstep-badge {
  background: var(--g);
  padding: 6px 16px;
  display: inline-block;
}

.pstep-badge span {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--n);
}

.pstep-r {
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding-top: 8px;
}

.pstep-h {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(24px, 3vw, 42px);
  font-weight: 800;
  color: var(--n);
  text-transform: uppercase;
  letter-spacing: -0.01em;
}

.pstep-p {
  font-size: 15px;
  font-weight: 500;
  line-height: 1.9;
  color: rgba(var(--n-rgb), 0.6);
}

.pstep-dets {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1px;
  background: rgba(var(--n-rgb), 0.06);
  margin-top: 8px;
}

.psd {
  background: var(--gr);
  padding: 22px 20px;
}

.psd-h {
  font-family: "League Spartan", sans-serif;
  font-size: 13px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--n);
  margin-bottom: 6px;
}

.psd-p {
  font-size: 12px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.5);
  line-height: 1.65;
}

.proc-guar {
  background: var(--g);
  padding: 80px 64px;
}

.pg-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1px;
  background: rgba(var(--n-rgb), 0.1);
}

.pgi {
  background: var(--g);
  padding: 44px 36px;
}

.pgi-n {
  font-family: "League Spartan", sans-serif;
  font-size: 54px;
  font-weight: 900;
  color: var(--n);
  line-height: 1;
  margin-bottom: 8px;
}

.pgi-h {
  font-family: "League Spartan", sans-serif;
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--n);
  margin-bottom: 8px;
}

.pgi-p {
  font-size: 13px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.6);
  line-height: 1.65;
}

/* ═══════════════ PROJECTS PAGE ═══════════════ */
.pf-bar {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98), rgba(255, 255, 255, 1));
  padding: 40px 64px 0;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.pf-btn {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  padding: 12px 24px;
  border: 1px solid rgba(var(--n-rgb), 0.12);
  border-radius: 999px;
  color: rgba(var(--n-rgb), 0.58);
  background: rgba(var(--n-rgb), 0.03);
  transition: all 0.3s ease;
  cursor: pointer;
}

.pf-btn.act,
.pf-btn:hover {
  background: var(--g);
  border-color: var(--g);
  color: var(--n);
  box-shadow: 0 12px 30px rgba(224, 171, 76, 0.25);
}

.pgrid {
  background: var(--w);
  padding: 28px 56px 120px;
}

.pg {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  grid-auto-flow: row;
}

.pgrid.all-view .pg {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
}

.pgrid.filtered-view .pg {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4px;
  align-items: stretch;
}

.pgcard {
  position: relative;
  overflow: hidden;
  aspect-ratio: 4 / 5;
  cursor: pointer;
  border-radius: 0;
  background: #0b121c;
  box-shadow: none;
  isolation: isolate;
}

.pgrid.filtered-view .pgcard {
  width: 100%;
  aspect-ratio: 4 / 5;
  grid-column: span 1 !important;
  min-height: 0;
  border-radius: 0;
  box-shadow: none;
}

.pgrid.all-view .pgcard {
  width: 100%;
  min-height: 0;
  grid-column: span 1;
  aspect-ratio: 16 / 19;
  border-radius: 0;
  box-shadow: none;
}

.pgrid.all-view .pgcard--feature {
  grid-column: span 1;
  aspect-ratio: 16 / 19;
}

.pgrid.all-view .pgcard--tall {
  grid-column: span 1;
  aspect-ratio: 16 / 19;
}

.pgrid.all-view .pgcard--soft {
  grid-column: span 1;
  aspect-ratio: 16 / 19;
}

.pgcard.is-filter-hidden {
  display: none !important;
}

.pgcard.wide {
  grid-column: span 1;
  aspect-ratio: 4 / 5;
}

.pgrid.filtered-view .pgcard.wide {
  grid-column: span 1;
  aspect-ratio: 4 / 5;
}

.pgrid.filtered-view .pgcard-inner {
  inset: 0;
}

.pgcard-inner {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  will-change: transform;
  transition: transform 0.1s linear;
  transform: scale(1.02);
}

.pgcard:hover .pgcard-inner {
  transform: scale(1.06) !important;
}

.pgcard-veil {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top,
      rgba(var(--n-rgb), 0.9) 0%,
      rgba(var(--n-rgb), 0.05) 50%,
      transparent 100%);
}

.pgcard-info {
  position: absolute;
  z-index: 2;
  bottom: 0;
  left: 0;
  right: 0;
  padding: 28px 28px 26px;
  transform: translateY(12px);
  transition: transform 0.5s var(--ease);
}

.pgcard:hover .pgcard-info {
  transform: none;
}

.pgrid.all-view .pgcard-info {
  padding: 28px 26px 24px;
}

.pgrid.all-view .pgcard-cat {
  display: none;
}

.pgrid.all-view .pgcard-name {
  font-size: clamp(24px, 2.2vw, 34px);
}

.pgrid.all-view .pgcard-veil {
  background: linear-gradient(to top,
      rgba(10, 18, 32, 0.88) 0%,
      rgba(10, 18, 32, 0.28) 42%,
      rgba(10, 18, 32, 0.06) 68%,
      transparent 100%);
}

.pgcard-cat {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 6px;
}

.pgcard-name {
  font-family: "League Spartan", sans-serif;
  font-size: clamp(20px, 2vw, 26px);
  font-weight: 700;
  color: var(--w);
  margin-bottom: 3px;
}

.pgcard-loc {
  font-size: 12px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
}

/* ═══════════════ CONTACT PAGE ═══════════════ */
.ct-body {
  background: var(--w);
  padding: 100px 64px 130px;
}

.ct-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 80px;
}

.ct-ways {
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: rgba(var(--n-rgb), 0.07);
}

.ct-way {
  background: var(--w);
  padding: 32px 36px;
  display: flex;
  gap: 22px;
  align-items: flex-start;
  transition: background 0.4s;
}

.ct-way:hover {
  background: rgba(var(--g-rgb), 0.05);
}

.ct-way-icon {
  width: 44px;
  height: 44px;
  background: var(--g);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ct-way-icon svg {
  width: 20px;
  height: 20px;
  stroke: var(--n);
  fill: none;
}

.ct-way-h {
  font-family: "League Spartan", sans-serif;
  font-size: 16px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--n);
  margin-bottom: 5px;
}

.ct-way-v {
  font-size: 14px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.55);
}

.ct-way-v a {
  color: var(--g);
  font-weight: 700;
}

.ct-ec {
  background: var(--n);
  padding: 40px 44px;
  margin-top: 22px;
}

.ctec-lbl {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--g);
  margin-bottom: 16px;
}

.ctec-h {
  font-family: "League Spartan", sans-serif;
  font-size: 24px;
  font-weight: 700;
  color: var(--w);
  margin-bottom: 8px;
}

.ctec-addr {
  font-style: normal;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
  line-height: 1.7;
  margin-bottom: 20px;
}

.ctec-hours {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ctec-hr {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.38);
}

.ctec-hr span:last-child {
  color: rgba(255, 255, 255, 0.65);
}

.ct-form-wrap {
  display: flex;
  flex-direction: column;
  gap: 22px;
  border: 1px #DDA851 solid;
  padding: 15px;
}

.ct-form-title {
  font-family: "League Spartan", sans-serif;
  font-size: 28px;
  font-weight: 700;
  color: var(--n);
}

.ct-form-sub {
  font-size: 14px;
  font-weight: 500;
  color: rgba(var(--n-rgb), 0.5);
  line-height: 1.7;
  margin-top: -12px;
}

.jf-progress {
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

.jf-progress-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 9px 14px;
  border-radius: 999px;
  background: rgba(var(--g-rgb), 0.12);
  border: 1px solid rgba(var(--g-rgb), 0.28);
  color: var(--n);
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.jf-step {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.jf-step[hidden] {
  display: none !important;
}

.jf-step.is-active {
  display: flex;
}

form.jf {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.jf-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.jf-field {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

.jf-lbl {
  font-family: "Quicksand", sans-serif;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.5);
}

.jf-inp,
.jf-sel,
.jf-ta {
  width: 100%;
  background: var(--gr);
  border: 1.5px solid transparent;
  padding: 14px 18px;
  font-family: "Quicksand", sans-serif;
  font-size: 14px;
  font-weight: 600;
  color: var(--n);
  outline: none;
  transition:
    border-color 0.3s,
    background 0.3s;
  cursor: none;
}

.jf-inp::placeholder,
.jf-ta::placeholder {
  color: rgba(var(--n-rgb), 0.3);
  font-weight: 500;
}

.jf-inp:focus,
.jf-sel:focus,
.jf-ta:focus {
  border-color: var(--g);
  background: rgba(var(--g-rgb), 0.05);
}

.jf-ta {
  resize: vertical;
  min-height: 130px;
}

.jf-sel {
  appearance: none;
  cursor: none;
}

.jf-sel option {
  background: var(--w);
}

/* Submit feedback */
.jf-notice {
  padding: 16px 20px;
  font-family: "Quicksand", sans-serif;
  font-size: 13px;
  font-weight: 600;
  display: none;
}

.jf-notice.ok {
  background: rgba(var(--g-rgb), 0.12);
  color: var(--n);
  border: 1px solid rgba(var(--g-rgb), 0.3);
}

.jf-notice.err {
  background: rgba(220, 50, 50, 0.08);
  color: #c0392b;
  border: 1px solid rgba(220, 50, 50, 0.2);
}

.jf-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
}

.jf-actions .mbtn {
  min-width: 170px;
}

.jf-back {
  background: transparent;
}

.jf-back .mbtn-bg {
  background: rgba(var(--n-rgb), 0.08);
}

.jf-back .mbtn-lbl {
  color: var(--n);
}

.jf-back:hover .mbtn-bg {
  transform: scale(1.03);
}

.map-sec {
  height: 380px;
  position: relative;
  overflow: hidden;
}

.map-bg {
  position: absolute;
  inset: 0;
  opacity: 1;
}

.map-content {
  position: relative;
  z-index: 1;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 14px;
}

.map-content h3 {
  font-family: "League Spartan", sans-serif;
  font-size: 22px;
  font-weight: 700;
  color: #000000;
}

.map-content p {
  font-size: 14px;
  font-weight: 500;
  color: #000000 !important;
}

.map-badge {
  padding: 10px 26px;
  display: inline-flex;
  margin-top: 6px;
}

.map-badge span {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--n);
}

/* ═══════════════ CRM DASHBOARD ═══════════════ */
#crm-page {
  display: none;
  position: fixed;
  inset: 0;
  z-index: 9990;
  background: var(--gr);
  overflow-y: auto;
}

.crm-nav {
  background: var(--n);
  padding: 18px 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 10;
}

.crm-logo {
  font-family: "League Spartan", sans-serif;
  font-size: 18px;
  font-weight: 800;
  color: var(--w);
  letter-spacing: 0.05em;
}

.crm-logo .dot {
  color: var(--g);
}

.crm-close {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
  background: rgba(255, 255, 255, 0.08);
  border: none;
  padding: 10px 22px;
  cursor: pointer;
  transition: background 0.3s;
}

.crm-close:hover {
  background: rgba(255, 255, 255, 0.15);
}

.crm-body {
  padding: 40px;
}

.crm-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-bottom: 32px;
}

.crm-stat {
  background: var(--w);
  padding: 28px 24px;
}

.crm-stat-n {
  font-family: "League Spartan", sans-serif;
  font-size: 42px;
  font-weight: 900;
  color: var(--n);
  line-height: 1;
  display: block;
}

.crm-stat-l {
  font-family: "Quicksand", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.4);
  display: block;
  margin-top: 4px;
}

.crm-stat.gold-card {
  background: var(--g);
}

.crm-stat.gold-card .crm-stat-n,
.crm-stat.gold-card .crm-stat-l {
  color: var(--n);
}

.crm-actions {
  display: flex;
  gap: 12px;
  align-items: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.crm-filter {
