/* Scroll to top */
.scroll-top {
  --scroll-progress: 0deg;
  position: fixed;
  right: clamp(16px, 3vw, 34px);
  bottom: clamp(18px, 3vw, 34px);
  z-index: 9990;
  display: grid;
  place-items: center;
  width: 56px;
  height: 56px;
  border: 1px solid rgba(var(--g-rgb), 0.55);
  border-radius: 50%;
  background:
    conic-gradient(var(--g) var(--scroll-progress), rgba(255, 255, 255, 0.2) 0),
    var(--n);
  color: var(--w);
  box-shadow: 0 18px 44px rgba(var(--n-rgb), 0.28);
  cursor: none;
  opacity: 0;
  pointer-events: none;
  transform: translateY(18px) scale(0.82);
  transition:
    opacity 0.35s var(--ease),
    transform 0.45s var(--ease),
    box-shadow 0.35s var(--ease);
}

.scroll-top::before {
  content: "";
  position: absolute;
  inset: 6px;
  border-radius: inherit;
  background: linear-gradient(145deg, var(--g), #f0c77f);
  transform: scale(0.92);
  transition: transform 0.35s var(--ease);
}

.scroll-top__ring {
  position: absolute;
  inset: -7px;
  border: 1px solid rgba(var(--g-rgb), 0.3);
  border-radius: inherit;
  opacity: 0;
  transform: scale(0.8);
}

.scroll-top__arrow {
  position: relative;
  z-index: 1;
  color: var(--n);
  font-family: "League Spartan", sans-serif;
  font-size: 28px;
  font-weight: 800;
  line-height: 1;
  transform: translateY(1px);
}

.scroll-top.is-visible {
  opacity: 1;
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

.scroll-top.is-visible .scroll-top__ring {
  animation: scrollTopPulse 1.8s var(--ease) infinite;
}

.scroll-top:hover,
.scroll-top:focus-visible {
  box-shadow: 0 24px 58px rgba(var(--n-rgb), 0.36);
  transform: translateY(-5px) scale(1.04);
}

.scroll-top:hover::before,
.scroll-top:focus-visible::before {
  transform: scale(1);
}

.scroll-top:focus-visible {
  outline: 3px solid rgba(var(--g-rgb), 0.45);
  outline-offset: 4px;
}

@keyframes scrollTopPulse {
  0% {
    opacity: 0.8;
    transform: scale(0.78);
  }

  70% {
    opacity: 0;
    transform: scale(1.28);
  }

  100% {
    opacity: 0;
    transform: scale(1.28);
  }
}

@media (max-width: 640px) {
  .scroll-top {
    width: 48px;
    height: 48px;
    right: 14px;
    bottom: 16px;
  }

  .scroll-top::before {
    inset: 5px;
  }

  .scroll-top__arrow {
    font-size: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .scroll-top,
  .scroll-top::before,
  .scroll-top__ring {
    animation: none !important;
    transition: none !important;
  }
}

