/* ═══════════════ PRELOADER ═══════════════ */
body.pl-lock {
  overflow: hidden;
}

.preloader {
  position: fixed;
  inset: 0;
  z-index: 100000;
  background: var(--w);
}

.pl-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
  background:
    radial-gradient(120% 140% at 50% 50%, rgba(var(--g-rgb), 0.08), transparent 60%),
    var(--w);
  transition: transform 0.9s cubic-bezier(0.76, 0, 0.24, 1) 0.35s;
}

.pl-panel-l {
  left: 0;
}

.pl-panel-r {
  right: 0;
}

.preloader-inner {
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  transition: opacity 0.5s var(--ease-out), transform 0.5s var(--ease-out);
}

.pl-sketch {
  width: 108px;
  height: auto;
  overflow: visible;
}

.pl-sketch .pl-line {
  fill: none;
  stroke: var(--g);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  filter: drop-shadow(0 0 6px rgba(var(--g-rgb), 0.45));
  animation: pl-draw 2.6s var(--ease) infinite;
}

.pl-sketch .pl-wall {
  animation-delay: 0.25s;
}

.pl-sketch .pl-door {
  animation-delay: 0.55s;
}

.pl-sketch .pl-window {
  animation-delay: 0.75s;
}

.pl-ring {
  fill: none;
  stroke: rgba(var(--g-rgb), 0.25);
  stroke-width: 1;
  stroke-dasharray: 4 7;
  transform-origin: 100px 82px;
  animation: pl-spin 7s linear infinite;
}

@keyframes pl-draw {

  0%,
  8% {
    stroke-dashoffset: 340;
    opacity: 0.35;
  }

  45%,
  70% {
    stroke-dashoffset: 0;
    opacity: 1;
  }

  92%,
  100% {
    stroke-dashoffset: 0;
    opacity: 0.35;
  }
}

@keyframes pl-spin {
  to {
    transform: rotate(360deg);
  }
}

.pl-word {
  font-family: "League Spartan", sans-serif;
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--n);
  opacity: 0;
  transform: translateY(10px);
  animation: pl-fade-up 0.7s var(--ease-out) 0.4s forwards;
}

.pl-word .jomo-brand,
.pl-word .jomo-brand:hover {
  color: var(--n);
}

.pl-word .jomo-dot {
  color: var(--g);
}

.pl-tag {
  font-family: "Quicksand", sans-serif;
  font-size: 0.78rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: rgba(var(--n-rgb), 0.55);
  opacity: 0;
  transform: translateY(8px);
  animation: pl-fade-up 0.7s var(--ease-out) 0.6s forwards;
}

@keyframes pl-fade-up {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.pl-bar {
  width: 160px;
  height: 2px;
  border-radius: 2px;
  background: rgba(var(--n-rgb), 0.12);
  overflow: hidden;
  opacity: 0;
  animation: pl-fade-up 0.7s var(--ease-out) 0.75s forwards;
}

.pl-bar-fill {
  display: block;
  width: 40%;
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(90deg, transparent, var(--g), transparent);
  animation: pl-sweep 1.4s ease-in-out infinite;
}

@keyframes pl-sweep {
  0% {
    transform: translateX(-120%);
  }

  100% {
    transform: translateX(360%);
  }
}

/* Exit transition: doors open to reveal the site */
.preloader.pl-exit {
  pointer-events: none;
}

.preloader.pl-exit .preloader-inner {
  opacity: 0;
  transform: scale(0.92);
  transition: opacity 0.35s var(--ease-out), transform 0.35s var(--ease-out);
}

.preloader.pl-exit .pl-panel-l {
  transform: translateX(-101%);
}

.preloader.pl-exit .pl-panel-r {
  transform: translateX(101%);
}

@media (max-width: 600px) {
  .pl-sketch {
    width: 84px;
  }

  .pl-word {
    font-size: 1.5rem;
  }

  .pl-tag {
    font-size: 0.68rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .pl-sketch .pl-line {
    animation: none;
    stroke-dashoffset: 0;
    opacity: 1;
  }

  .pl-bar-fill {
    animation: none;
    width: 100%;
  }

  .preloader,
  .preloader-inner,
  .pl-panel {
    transition-duration: 0.01ms !important;
  }
}
